/**
 * kon-blog
 *
 * Publishing platform with rich text editor, scheduling, tags, and SEO overrides.
 */
export interface BlogApi {
  /**
   * Delete a blog category
   *
   * Deletes a category. Its posts stay; they just lose the category.
   *
   * REST: `DELETE /api/blog/categories/{id}` · scope `kon:blog:borrar-categoria`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `blog__borrar-categoria`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly borrarCategoria: Operation<BorrarCategoriaParams, BorrarCategoriaResponse>;
  /**
   * Delete a post
   *
   * Deletes a post and its tag/game links. Cannot be undone.
   *
   * REST: `DELETE /api/blog/{id}` · scope `kon:blog:borrar-entrada`
   * idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval · MCP tool `blog__borrar-entrada`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly borrarEntrada: Operation<BorrarEntradaParams, BorrarEntradaResponse>;
  /**
   * Create a blog category
   *
   * Creates a category (optionally under a parent).
   *
   * REST: `POST /api/blog/categories` · scope `kon:blog:crear-categoria`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blog__crear-categoria`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearCategoria: Operation<CrearCategoriaParams, CrearCategoriaResponse>;
  /**
   * Create a post
   *
   * Creates a post (draft by default) with its tags, games and categories. Content and blocks are sanitized; the slug is derived from the title when missing. publishedAt is an ISO 8601 date.
   *
   * REST: `POST /api/blog` · scope `kon:blog:crear-entrada`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blog__crear-entrada`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly crearEntrada: Operation<CrearEntradaParams, CrearEntradaResponse>;
  /**
   * Update a blog category
   *
   * Renames, moves or reorders a category (a category cannot be its own ancestor).
   *
   * REST: `PATCH /api/blog/categories/{id}` · scope `kon:blog:editar-categoria`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blog__editar-categoria`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarCategoria: Operation<EditarCategoriaParams, EditarCategoriaResponse>;
  /**
   * Update a post
   *
   * Changes the given fields and, if sent, replaces its tags/games/categories. publishedAt (ISO 8601, or null) schedules or unschedules it. Send expectedUpdatedAt (the updatedAt you loaded) to get a 409 instead of overwriting someone else's save.
   *
   * REST: `PATCH /api/blog/{id}` · scope `kon:blog:editar-entrada`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blog__editar-entrada`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_CONFLICT`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly editarEntrada: Operation<EditarEntradaParams, EditarEntradaResponse>;
  /**
   * Source of a promoted post
   *
   * The source record a post was promoted from (staff only: it carries the whole source row).
   *
   * REST: `GET /api/blog/source/{postId}` · scope `kon:blog:fuente-de-entrada`
   * idempotent (safe to retry) · MCP tool `blog__fuente-de-entrada`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly fuenteDeEntrada: Operation<FuenteDeEntradaParams, FuenteDeEntradaResponse>;
  /**
   * GEO payload of a post
   *
   * The answer-engine payload of a published post: BLUF, FAQ and the API-friendly summary.
   *
   * REST: `GET /api/blog/geo/{slug}` · scope `kon:blog:geo-de-entrada`
   * idempotent (safe to retry) · MCP tool `blog__geo-de-entrada`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly geoDeEntrada: Operation<GeoDeEntradaParams, GeoDeEntradaResponse>;
  /**
   * List blog categories
   *
   * Every category as a flat list with parentId and postCount (build the tree on the client).
   *
   * REST: `GET /api/blog/categories` · scope `kon:blog:listar-categorias`
   * idempotent (safe to retry) · MCP tool `blog__listar-categorias`
   * Errors: `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarCategorias: Operation<void, ListarCategoriasResponse>;
  /**
   * List blog posts
   *
   * Paginated posts, newest first, filterable by category (slug or uuid), game (uuid), text in title/excerpt and locale (one version per translation group: the asked locale, else English, else the newest). The public only sees published posts whose date has come; staff can ask for any status or 'all'.
   *
   * REST: `GET /api/blog` · scope `kon:blog:listar-entradas`
   * idempotent (safe to retry) · MCP tool `blog__listar-entradas`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly listarEntradas: PageableOperation<ListarEntradasParams, ListarEntradasResponse, ListarEntradasItem>;
  /**
   * Get a post by id
   *
   * One post by uuid (same shape as by slug). Unpublished posts are a 404 for the public.
   *
   * REST: `GET /api/blog/{id}` · scope `kon:blog:obtener-entrada`
   * idempotent (safe to retry) · MCP tool `blog__obtener-entrada`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly obtenerEntrada: Operation<ObtenerEntradaParams, ObtenerEntradaResponse>;
  /**
   * Get a post by slug
   *
   * One post by slug with its author, tag and game ids, rendered blocks (blocksHtml), translations and comment thread info. Unpublished posts are a 404 for the public.
   *
   * REST: `GET /api/blog/slug/{slug}` · scope `kon:blog:obtener-por-slug`
   * idempotent (safe to retry) · MCP tool `blog__obtener-por-slug`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly obtenerPorSlug: Operation<ObtenerPorSlugParams, ObtenerPorSlugResponse>;
  /**
   * Create a post from a dataset entry
   *
   * Creates a draft (or published) post from a dataset entry, or from a kon table row (admin only, never account/secret tables).
   *
   * REST: `POST /api/blog/promote-from-source` · scope `kon:blog:promover-desde-fuente`
   * not idempotent (an Idempotency-Key is sent automatically) · MCP tool `blog__promover-desde-fuente`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly promoverDesdeFuente: Operation<PromoverDesdeFuenteParams, PromoverDesdeFuenteResponse>;
  /**
   * Publish a post now
   *
   * Sets the post to published with publishedAt = now.
   *
   * REST: `POST /api/blog/{id}/publish` · scope `kon:blog:publicar-entrada`
   * not idempotent (an Idempotency-Key is sent automatically) · sensitive: may come back as a proposal pending human approval · MCP tool `blog__publicar-entrada`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly publicarEntrada: Operation<PublicarEntradaParams, PublicarEntradaResponse>;
  /**
   * Ask Facebook to re-scrape a post
   *
   * Asks the Facebook Graph API to refresh its Open Graph cache for the post URL (an outbound call).
   *
   * REST: `POST /api/blog/{slug}/refresh-og-cache` · scope `kon:blog:refrescar-cache-og`
   * idempotent (safe to retry)
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_BAD_GATEWAY`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly refrescarCacheOg: Operation<RefrescarCacheOgParams, RefrescarCacheOgResponse>;
  /**
   * SEO metadata of a post
   *
   * Full SEO/Open Graph/structured-data metadata for a published post (404 if not visible).
   *
   * REST: `GET /api/blog/seo/{slug}` · scope `kon:blog:seo-de-entrada`
   * idempotent (safe to retry) · MCP tool `blog__seo-de-entrada`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly seoDeEntrada: Operation<SeoDeEntradaParams, SeoDeEntradaResponse>;
  /**
   * Validate a social image
   *
   * Checks an image (URL, size, weight, type) against what WhatsApp/Open Graph previews need. Read-only; staff tool.
   *
   * REST: `POST /api/blog/validate-image` · scope `kon:blog:validar-imagen`
   * idempotent (safe to retry) · MCP tool `blog__validar-imagen`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly validarImagen: Operation<ValidarImagenParams, ValidarImagenResponse>;
  /**
   * Validate SEO fields
   *
   * Scores title, description, excerpt, keyword and image against the SEO limits. Read-only; staff tool.
   *
   * REST: `POST /api/blog/validate-seo` · scope `kon:blog:validar-seo`
   * idempotent (safe to retry) · MCP tool `blog__validar-seo`
   * Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
   */
  readonly validarSeo: Operation<ValidarSeoParams, ValidarSeoResponse>;
}
